  ?fund a gleif-L1:Fund ;
        gleif-L1:hasLegalName "VDDKO - MASTERFONDS" .
  ?fund kgx:hasFundManager ?mgr .
  ?mgr gleif-L1:hasLegalName ?managerName .
}

